from fractions import Fraction as F
from math import factorial
def b(n,k):
 r=F(1)
 for i in range(k):r*=F(n-i,i+1)
 return r
def c(g,q,a,s):
 h={-a-g+j:F(factorial(g))*b(-a,g-j)*b(a-4,j)*(-1)**j for j in range(g+1)};Q=q+2;z=-1 if s=='-' else 1;o={}
 for e,x in h.items():
  v=e+1+z*Q;o[e]=o.get(e,F())+x*v;o[e+1]=o.get(e+1,F())+x*(v-g)
 o={e:x for e,x in o.items() if x};return o if s=='-' else {e+Q:-x for e,x in o.items()}
def sub(v,w,z):
 for e,x in w.items():
  v[e]=v.get(e,F())-z*x
  if not v[e]:del v[e]
def build(N):
 E=[];R=[];P=[];B=[];D={}
 for a in range(N+1):
  for s in '-+':
   v=c(6,3,a,s);r={}
   for i,p in enumerate(P):
    z=v.get(p,F())
    if z:
     sub(v,E[i],z)
     for j,x in R[i].items():r[j]=r.get(j,F())-z*x
   if v:
    p=min(v);z=v[p];E.append({e:x/z for e,x in v.items()});r={j:x/z for j,x in r.items()};r[len(P)]=F(1,z);R.append(r);P.append(p);B.append((a,s))
   else:D[(a,s)]={j:-x for j,x in r.items()}
 return B,D
B,D=build(120)
for N in [20,40,60,80,100,120]:
 for rho in [1.,1.05,1.1]:
  rows=[0.]*len(B);cols=[]
  for (a,s),r in D.items():
   if s!='+' or a>N:continue
   z=0.
   for j,x in r.items():
    y=float(abs(x))*rho**(B[j][0]-a);z+=y;rows[j]+=y
   cols.append(z)
  print(N,rho,f'{max(cols):.4g}',f'{max(rows):.4g}')
